extends Node2D
## BattleView — the playable battle scene (v1: grid, click input, ghost rendering).
##
## DOCTRINE (Godot Dev Bible + project invariants):
## - Determinism is law: the view NEVER writes floats or positions back into the
##   sim. All writes go through tm.on_player_command() with integer cells.
##   Board math (cell<->pixel) lives here and only here.
## - Call down, signal up: the view commands the TurnManager (down); the
##   TurnManager emits round_started/round_ended/battle_ended (up) and the
##   view listens. No upward get_parent() navigation anywhere.
## - Gameplay input via _unhandled_input so UI (Buttons) never eats clicks.
## - Ghosts already replayed at round start; they render where their orders left
##   them, as allies you cannot command. Clicking a ghost shows its recorded
##   orders (the 30-second-teach preview) as violet path tiles.

const CELL: float = 32.0
const GRID_W: int = 8
const GRID_H: int = 8
const ENCOUNTER_PATH := "res://data/encounters/encounter_01.json"
const MODE_GHOST: int = 2   # GridIndicators.Mode.GHOST (enum: MOVE=0, ATTACK=1, GHOST=2)

var tm: Node
var encounter: Dictionary = {}
var selected_id: String = ""

@onready var board: Node2D = $Board
@onready var tokens: Node2D = $Board/Tokens
@onready var indicators: Node2D = $Board/Indicators
@onready var round_label: Label = $UI/RoundLabel
@onready var msg_label: Label = $UI/MsgLabel
@onready var end_btn: Button = $UI/EndRoundButton

func _ready() -> void:
	# The TurnManager is a child of the view (call-down). Loaded by path, not
	# class_name, so batch edits + headless runs don't depend on scan order.
	tm = load("res://scripts/battle/turn_manager.gd").new()
	tm.name = "TurnManager"
	add_child(tm)
	tm.round_started.connect(_on_round_started)
	tm.round_ended.connect(_on_round_ended)
	tm.battle_ended.connect(_on_battle_ended)
	end_btn.pressed.connect(_on_end_round_pressed)
	encounter = _load_encounter()
	tm.start_battle(encounter)

func _load_encounter() -> Dictionary:
	var f := FileAccess.open(ENCOUNTER_PATH, FileAccess.READ)
	assert(f != null, "missing encounter file: " + ENCOUNTER_PATH)
	var parsed = JSON.parse_string(f.get_as_text())
	assert(parsed is Dictionary, "encounter JSON did not parse")
	return parsed

# ---------- board math (the ONLY place pixels and cells meet) ----------

func cell_to_token_pos(x: int, y: int) -> Vector2:
	return Vector2(x * CELL + CELL / 2.0, y * CELL + CELL / 2.0)

func screen_to_cell(screen: Vector2) -> Vector2:
	var local: Vector2 = (screen - board.global_position) / board.scale.x / CELL
	return Vector2(floor(local.x), floor(local.y))

# ---------- signals from the TurnManager (up) ----------

func _on_round_started(round_number: int) -> void:
	selected_id = ""
	indicators.clear()
	end_btn.disabled = false
	round_label.text = "Round %d / 3" % round_number
	if round_number == 1:
		_say("Your squad awaits orders. Click a unit, then a tile to move or an enemy to attack.")
	else:
		_say("Round %d — the echoes have already replayed their final orders. Ghosts: click one to see its fate." % round_number)
	_render()

func _on_round_ended(_round_number: int, _recording: Array) -> void:
	pass  # the next round_started (or battle_ended) re-renders

func _on_battle_ended(victory: bool) -> void:
	end_btn.disabled = true
	if victory:
		round_label.text = "VICTORY"
		_say("VICTORY — the shades are laid to rest. The séance closes.")
	else:
		round_label.text = "DEFEAT"
		_say("DEFEAT — the living join the Company.")
	_render()

func _on_end_round_pressed() -> void:
	if not tm.battle_over:
		tm.end_round()

# ---------- rendering ----------

func _render() -> void:
	for child in tokens.get_children():
		child.queue_free()
	for id in tm.sim.units.keys().sorted():
		var u: Dictionary = tm.sim.units[id]
		if not bool(u["alive"]):
			continue
		var token: Node2D = load("res://scripts/battle/unit_token.gd").new()
		tokens.add_child(token)
		token.name = "Token_%s" % id
		token.position = cell_to_token_pos(int(u["x"]), int(u["y"]))
		token.setup(u)
		token.selected = id == selected_id

func _select(id: String) -> void:
	selected_id = id
	for child in tokens.get_children():
		var unit_id: String = String(child.name).trim_prefix("Token_")
		child.selected = unit_id == id

func _clear_selection() -> void:
	selected_id = ""
	for child in tokens.get_children():
		child.selected = false

func _say(text: String) -> void:
	msg_label.text = text

# ---------- gameplay input (unhandled, so UI never eats it) ----------

func _unhandled_input(event: InputEvent) -> void:
	if tm.battle_over:
		return
	if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		var cell: Vector2 = screen_to_cell(event.position)
		var cx: int = int(cell.x)
		var cy: int = int(cell.y)
		if cx < 0 or cy < 0 or cx >= GRID_W or cy >= GRID_H:
			_clear_selection()
			return
		var clicked_id: String = tm.sim.unit_at(cx, cy)
		if selected_id.is_empty():
			_try_select(clicked_id)
		elif clicked_id.is_empty():
			tm.on_player_command(selected_id, "move", {"x": cx, "y": cy})
			_say("Moved. Next order, or End Round.")
			_clear_selection()
			_render()
		elif _is_enemy(clicked_id):
			tm.on_player_command(selected_id, "attack", {"x": cx, "y": cy})
			var t: Dictionary = tm.sim.units[clicked_id]
			if bool(t["alive"]):
				_say("Hit — the shade endures (hp %d)." % int(t["hp"]))
			else:
				_say("The shade is destroyed.")
			_clear_selection()
			_render()
		elif clicked_id == selected_id:
			_clear_selection()
		elif _is_living(clicked_id):
			_select(clicked_id)
			_say("Selected. Click a tile to move or an enemy to attack.")
		elif _is_ghost(clicked_id):
			_show_echo_preview(clicked_id)
		get_viewport().set_input_as_handled()

## A ghost's recorded orders, drawn as violet path tiles (the 30-second teach).
func _show_echo_preview(ghost_id: String) -> void:
	var u: Dictionary = tm.sim.units[ghost_id]
	var echo_index: int = int(u.get("echo", 0))
	var origin_id: String = ghost_id.substr(ghost_id.find("_") + 1)  # "e0_marksman" -> "marksman"
	var recording: Array = tm.preview_echo(echo_index)
	var cells: Array = []
	for cmd in recording:
		if String(cmd["unit_id"]) != origin_id:
			continue
		if cmd["args"].has("x") and cmd["args"].has("y"):
			cells.append(Vector2(int(cmd["args"]["x"]), int(cmd["args"]["y"])))
	indicators.clear()
	indicators.show_tiles(cells, MODE_GHOST)
	_say("Echo %d's final orders — it repeats them every round, forever." % (echo_index + 1))

func _is_enemy(id: String) -> bool:
	return String(tm.sim.units.get(id, {}).get("faction", "")) == "enemy"

func _is_living(id: String) -> bool:
	var u: Dictionary = tm.sim.units.get(id, {})
	return not u.is_empty() and String(u.get("faction", "player")) != "enemy" and not bool(u.get("ghost", false))

func _is_ghost(id: String) -> bool:
	return bool(tm.sim.units.get(id, {}).get("ghost", false))

func _try_select(id: String) -> void:
	if id.is_empty():
		_clear_selection()
		indicators.clear()
	elif _is_living(id):
		_select(id)
		_say("Selected. Click a tile to move or an enemy to attack.")
	elif _is_ghost(id):
		_show_echo_preview(id)
	elif _is_enemy(id):
		_say("An enemy shade. Select one of yours first.")
